"""Literal parser,raw mapping and independent ordered eligible-union controls."""

ORIGINAL = 'impl StringFamily{\n    fn original_targets(&self, string_id: &str) -> Vec<String> {\n        if !self.contains_active(string_id) {\n            return Vec::new();\n        }\n        let active_ids: Vec<String> = self\n            .active_member_ids()\n            .iter()\n            .map(|s| s.to_string())\n            .collect();\n        let mut targets = Vec::new();\n        for rule in &self.propagation_rules {\n            if rule.targets_all() {\n                // "All members" means all active members except source\n                for m in &active_ids {\n                    if m != string_id && !targets.contains(m) {\n                        targets.push(m.clone());\n                    }\n                }\n            } else {\n                for t in &rule.targets {\n                    if t != string_id && !targets.contains(t) && active_ids.contains(t) {\n                        targets.push(t.clone());\n                    }\n                }\n            }\n        }\n        targets\n    }\n}\n'

TESTS = r'''
fn live(status:&MemberStatus)->bool{matches!(status,MemberStatus::Exists)}
fn expected(f:&StringFamily,source:&str)->Vec<String>{if !f.members.iter().any(|m|m.string_id==source&&live(&m.status)){return Vec::new();}let mut out:Vec<&str>=Vec::new();for rule in &f.propagation_rules{let candidates:Vec<&str>=if rule.targets.iter().any(|x|x=="All members"){f.members.iter().filter(|m|live(&m.status)).map(|m|m.string_id.as_str()).collect()}else{rule.targets.iter().map(String::as_str).collect()};for c in candidates{if c!=source&&f.members.iter().any(|m|m.string_id==c&&live(&m.status))&&!out.contains(&c){out.push(c);}}}out.into_iter().map(str::to_owned).collect()}
#[test]fn literal_severity_and_status_parsing(){
 let cases=[("CRITICAL",Severity::Critical),("critical",Severity::Critical),("crıtıcal",Severity::Critical),("hıgh",Severity::High),("HIGH",Severity::High),("Medium",Severity::Medium),("LOW",Severity::Low),(" critical ",Severity::Low),("ΜEDIUM",Severity::Low),("",Severity::Low),("\0CRITICAL",Severity::Low)];for (label,want) in cases{assert_eq!(Severity::parse(label),want);}let levels=[Severity::Critical,Severity::High,Severity::Medium,Severity::Low];for (i,level) in levels.iter().enumerate(){assert_eq!(level.to_string(),["CRITICAL","HIGH","MEDIUM","LOW"][i]);for (j,other) in levels.iter().enumerate(){assert_eq!(level.cmp(other),i.cmp(&j));}}
 let cases=[("EXISTS",MemberStatus::Exists),(" \tEXISTS\u{2003}",MemberStatus::Exists),("exists",MemberStatus::Planned),("PLANNED",MemberStatus::Planned),("unknown",MemberStatus::Planned),("CONSOLIDATED -> target",MemberStatus::Consolidated{target:"target".into()}),("CONSOLIDATED ->",MemberStatus::Planned),("DEPRECATED -> target",MemberStatus::Deprecated{target:"target".into()}),("DEPRECATED -> consolidated into target",MemberStatus::Deprecated{target:"target".into()}),("DEPRECATED -> consolidated into",MemberStatus::Deprecated{target:"consolidated into".into()}),("DEPRECATED -> consolidated into   x ",MemberStatus::Deprecated{target:"  x".into()}),("DEPRECATED ->  x ",MemberStatus::Deprecated{target:" x".into()}),("\0EXISTS",MemberStatus::Planned),("\u{2003}CONSOLIDATED -> λ\0\u{2003}",MemberStatus::Consolidated{target:"λ\0".into()})];for (label,want) in cases{let actual=MemberStatus::parse(label);assert_eq!(actual,want);assert_eq!(actual.is_active(),live(&want));}
}
#[test]fn constructors_lists_and_unchecked_name_maps(){
 for label in [""," x ","λ\0"]{let c=Constraint::new(label,"desc",Severity::High);assert_eq!((&*c.id,&*c.description,c.severity),(label,"desc",Severity::High));let rule=PropagationRule::new(label,"example",vec![label.into(),"same".into()]);assert_eq!((&*rule.pattern,&*rule.example),(label,"example"));assert_eq!(rule.targets,vec![label,"same"]);assert!(!rule.targets_all());let m=FamilyMember::new(label,MemberStatus::Planned);assert_eq!(m.string_id,label);assert_eq!(m.status,MemberStatus::Planned);let m=FamilyMember::active(label);assert_eq!(m.string_id,label);assert_eq!(m.status,MemberStatus::Exists);
  let family=StringFamily::new(label,"family desc");assert_eq!((&*family.id,&*family.description),(label,"family desc"));assert!(family.members.is_empty()&&family.constraints.is_empty()&&family.propagation_rules.is_empty()&&family.related_strings.is_empty());let mut f=FamilyFunctor::from_family(family);assert_eq!(f.id(),label);assert_eq!(f.family.description,"family desc");assert!(f.constraint_to_capabilities.is_empty()&&f.propagation_to_strings.is_empty());f.map_constraint("unregistered","one".into());f.map_propagation("unregistered","prop".into());f.map_constraint("unregistered","one".into());f.map_constraint("other","two".into());f.map_propagation("unregistered","prop2".into());assert_eq!(f.apply_constraint("unregistered").into_iter().map(String::as_str).collect::<Vec<_>>(),["one","one"]);assert_eq!(f.apply_constraint("other").into_iter().map(String::as_str).collect::<Vec<_>>(),["two"]);assert_eq!(f.apply_propagation("unregistered").into_iter().map(String::as_str).collect::<Vec<_>>(),["prop","prop2"]);assert!(f.apply_constraint("missing").is_empty());assert!(f.apply_propagation("missing").is_empty());for (i,x) in f.apply_constraint("unregistered").iter().enumerate(){assert!(std::ptr::eq(*x,&f.constraint_to_capabilities["unregistered"][i]));}
 }
}
#[test]fn exhaustive_status_rule_order_and_duplicate_members(){
 let statuses=[MemberStatus::Exists,MemberStatus::Planned,MemberStatus::Consolidated{target:"x".into()},MemberStatus::Deprecated{target:"x".into()}];let rules:Vec<Vec<String>>=vec![vec![],vec!["a"],vec!["b"],vec!["a","b"],vec!["b","a","b"],vec!["All members"],vec!["missing","All members","a"],vec!["all members","","missing"]].into_iter().map(|v|v.into_iter().map(str::to_owned).collect()).collect();let mut cases=0;
 for code in 0..64{let mut n=code;let mut f=StringFamily::new("F","");for id in ["a","b","a"]{let state=n%4;n/=4;f.members.push(FamilyMember::new(id,statuses[state].clone()));}let indices:Vec<_>=f.members.iter().enumerate().filter_map(|(i,m)|live(&m.status).then_some(i)).collect();let active=f.active_members();assert_eq!(active.len(),indices.len());for (x,&i) in active.iter().zip(&indices){assert!(std::ptr::eq(*x,&f.members[i]));}assert_eq!(f.active_member_ids(),indices.iter().map(|&i|f.members[i].string_id.as_str()).collect::<Vec<_>>());
  for left in &rules{for right in &rules{f.propagation_rules=vec![PropagationRule::new("r","",left.clone()),PropagationRule::new("r","",right.clone())];for source in ["a","b","missing"]{assert_eq!(f.contains_active(source),f.members.iter().any(|m|m.string_id==source&&live(&m.status)));let want=expected(&f,source);assert_eq!(f.get_propagation_targets(source),want);assert_eq!(f.get_propagation_targets(source),f.original_targets(source));let runtime=FamilyFunctor::from_family(f.clone());assert_eq!(runtime.get_propagation_targets(source),want);cases+=1;}}}
 }assert_eq!(cases,12288);
 let mut f=StringFamily::new("","");for id in ["x","All members","all members","","λ\0"]{f.members.push(FamilyMember::active(id));}f.members.push(FamilyMember::new("inactive",MemberStatus::Planned));for targets in &rules{f.propagation_rules=vec![PropagationRule::new("literal","",targets.clone())];for source in ["x","All members","all members","","λ\0","inactive"]{assert_eq!(f.get_propagation_targets(source),expected(&f,source));}}let rule=PropagationRule::new("","",vec![" All members".into()]);assert!(!rule.targets_all());
}
'''


def challenge(subject):
    return '\n#[cfg(test)]mod independent_family_tests{use super::*;\n'+ORIGINAL+TESTS+'\n}\n'
